/* Disposable, storage-free low fidelity interaction trial before world production. */
(()=>{'use strict';const W=RechtenWave,C=RechtenV2Workbench,root=document.querySelector('#prototype');let mode='interval',values={},feedback='';
function render(){const slope=mode==='delta';root.innerHTML=`<section class="mission-shell"><header class="mission-top"><button id="switch">${slope?'Grensselectie':'Gerichte verschillen'}</button><span>Losse mechaniekproef</span><a href="./">Naar de wereld</a></header><h1 class="mission-question">${slope?'Bouw de verplaatsing van A naar B.':'Selecteer x-waarden boven de x-as.'}</h1><div class="workspace"><div class="evidence">${C.graph({model:slope?null:{kind:'affine',a:W.q(1),b:W.q(-3)},points:slope?{A:{x:W.q(-2),y:W.q(-1)},B:{x:W.q(2),y:W.q(1)}}:{},anchor:values.root,region:values.side})}</div><form class="answer-tray" id="trial">${slope?`<div class="given-points">A (−2, −1) · B (2, 1)</div><div class="control-row">${C.field('dx','Δx',values.dx)}${C.field('dy','Δy',values.dy)}</div>`:`${C.field('root','Grens op de x-as',values.root)}<div class="control-row">${C.choice('side','Links','left',values.side)}${C.choice('side','Rechts','right',values.side)}</div>`}</form></div><footer class="mission-footer"><span></span><p class="feedback" role="status">${C.esc(feedback)}</p><button class="primary" id="test">Leg vast</button></footer></section><section id="rotateGate"><h1>Draai je toestel</h1><p>Deze mechaniekproef gebruikt een liggend scherm.</p><a href="./">Terug naar de wereld</a></section>`;root.querySelector('#switch').onclick=()=>{mode=slope?'interval':'delta';values={};feedback='';render()};root.querySelectorAll('input').forEach(i=>i.oninput=()=>values[i.name]=i.value);root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{values[b.dataset.choice]=b.dataset.value;render()});root.querySelector('#test').onclick=()=>{feedback=slope?`Je plan: Δx = ${values.dx||'…'}, Δy = ${values.dy||'…'}.`:`Je koos ${values.side==='left'?'links':values.side==='right'?'rechts':'nog geen regio'} van ${values.root||'…'}.`;render()};root.querySelector('form').onsubmit=e=>{e.preventDefault();root.querySelector('#test').click()};}
render();})();
